  if (R.sheltered) T += 7;
  // TODO(split): uses R
  if (R.nearFire) T += R.nearFireDist < 6 ? 26 : 26 * (1 - (R.nearFireDist - 6) / 4);
  if (heldDef().tool.cls === 'torch') T += 6;
